'use strict';

const Database = require('better-sqlite3');

/**
 * Create a todos database.
 * @param {':memory:'|string} [location] - ':memory:' for in-memory DB, or a file path.
 * @returns {import('better-sqlite3').Database}
 */
function createDb(location = ':memory:') {
  const db = new Database(location);
  db.pragma('journal_mode = WAL');
  db.exec(`
    CREATE TABLE IF NOT EXISTS todos (
      id INTEGER PRIMARY KEY,
      text TEXT NOT NULL,
      done INTEGER NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
    );
  `);

  // All statements are defined once and always executed with bound
  // parameters -- no user input is ever interpolated into SQL text.
  db.statements = {
    insert: db.prepare(
      'INSERT INTO todos (text) VALUES (?)'
    ),
    selectAll: db.prepare(
      'SELECT id, text, done, created_at FROM todos ORDER BY id'
    ),
    selectWhereDone: db.prepare(
      'SELECT id, text, done, created_at FROM todos WHERE done = ? ORDER BY id'
    ),
    selectById: db.prepare(
      'SELECT id, text, done, created_at FROM todos WHERE id = ?'
    ),
    updateText: db.prepare(
      'UPDATE todos SET text = ? WHERE id = ?'
    ),
    updateDone: db.prepare(
      'UPDATE todos SET done = ? WHERE id = ?'
    ),
    deleteById: db.prepare(
      'DELETE FROM todos WHERE id = ?'
    ),
  };

  return db;
}

module.exports = { createDb };

