'use strict';

const express = require('express');
const { createDb } = require('./db');

const ALLOWED_PATCH_FIELDS = ['text', 'done'];

function toBoolean(value) {
  return value === true || value === 1 || value === 'true';
}

function serialize(row) {
  return { ...row, done: Boolean(row.done) };
}

function createApp({ dbLocation = ':memory:' } = {}) {
  const db = createDb(dbLocation);
  const app = express();
  app.use(express.json());
  app.set('db', db);

  app.post('/todos', (req, res) => {
    const text = req.body && req.body.text;
    if (typeof text !== 'string' || text.trim() === '') {
      return res.status(400).json({
        error: "Field 'text' is required and must be a non-empty string.",
      });
    }
    const info = db.statements.insert.run(text);
    const row = db.statements.selectById.get(info.lastInsertRowid);
    return res.status(201).json(serialize(row));
  });

  app.get('/todos', (req, res) => {
    const { done } = req.query;
    let rows;
    if (done === undefined) {
      rows = db.statements.selectAll.all();
    } else if (done === 'true' || done === 'false') {
      rows = db.statements.selectWhereDone.all(done === 'true' ? 1 : 0);
    } else {
      return res.status(400).json({
        error: "Query parameter 'done' must be 'true' or 'false'.",
      });
    }
    return res.json(rows.map(serialize));
  });

  app.patch('/todos/:id', (req, res) => {
    const id = Number(req.params.id);
    if (!Number.isInteger(id)) {
      return res.status(400).json({ error: "'id' must be an integer." });
    }

    const body = req.body;
    if (body === null || typeof body !== 'object' || Array.isArray(body)) {
      return res
        .status(400)
        .json({ error: 'Request body must be a JSON object.' });
    }

    // Reject any fields outside the allowed set, listing them by name.
    const unknownFields = Object.keys(body).filter(
      (key) => !ALLOWED_PATCH_FIELDS.includes(key)
    );
    if (unknownFields.length > 0) {
      return res.status(400).json({
        error: `Unknown field(s): ${unknownFields.join(', ')}`,
        unknownFields,
      });
    }

    const existing = db.statements.selectById.get(id);
    if (!existing) {
      return res.status(404).json({ error: `Todo ${id} not found.` });
    }

    if ('text' in body) {
      if (typeof body.text !== 'string' || body.text.trim() === '') {
        return res.status(400).json({
          error: "Field 'text' must be a non-empty string.",
        });
      }
      db.statements.updateText.run(body.text, id);
    }
    if ('done' in body) {
      if (typeof body.done !== 'boolean') {
        return res
          .status(400)
          .json({ error: "Field 'done' must be a boolean." });
      }
      db.statements.updateDone.run(body.done ? 1 : 0, id);
    }

    const row = db.statements.selectById.get(id);
    return res.json(serialize(row));
  });

  app.delete('/todos/:id', (req, res) => {
    const id = Number(req.params.id);
    if (!Number.isInteger(id)) {
      return res.status(400).json({ error: "'id' must be an integer." });
    }
    const info = db.statements.deleteById.run(id);
    if (info.changes === 0) {
      return res.status(404).json({ error: `Todo ${id} not found.` });
    }
    return res.status(204).end();
  });

  // Error handler (e.g. malformed JSON bodies).
  // eslint-disable-next-line no-unused-vars
  app.use((err, req, res, next) => {
    if (err.type === 'entity.parse.failed') {
      return res.status(400).json({ error: 'Malformed JSON body.' });
    }
    console.error(err);
    return res.status(500).json({ error: 'Internal server error.' });
  });

  return app;
}

module.exports = { createApp };

