'use strict';

// Fresh in-memory DB per test file: createApp() builds a new ':memory:'
// database for this whole file; each test cleans the todos table so tests
// stay independent of one another.
const request = require('supertest');
const { createApp } = require('../src/app');

let app;
let db;

beforeAll(() => {
  app = createApp({ dbLocation: ':memory:' });
  db = app.get('db');
});

beforeEach(() => {
  db.exec('DELETE FROM todos');
});

afterAll(() => {
  db.close();
});

async function seedTodo(text = 'buy milk', done = false) {
  const res = await request(app).post('/todos').send({ text });
  expect(res.status).toBe(201);
  if (done) {
    const patchRes = await request(app)
      .patch(`/todos/${res.body.id}`)
      .send({ done: true });
    expect(patchRes.status).toBe(200);
    return patchRes.body;
  }
  return res.body;
}

describe('POST /todos', () => {
  test('creates a todo and returns it with defaults', async () => {
    const res = await request(app)
      .post('/todos')
      .send({ text: 'walk the dog' });

    expect(res.status).toBe(201);
    expect(res.body).toMatchObject({
      text: 'walk the dog',
      done: false,
    });
    expect(typeof res.body.id).toBe('number');
    expect(res.body.created_at).toMatch(/^\d{4}-\d{2}-\d{2}T/);
  });

  test('rejects missing or empty text with 400', async () => {
    const missing = await request(app).post('/todos').send({});
    expect(missing.status).toBe(400);

    const empty = await request(app).post('/todos').send({ text: '   ' });
    expect(empty.status).toBe(400);

    const wrongType = await request(app).post('/todos').send({ text: 42 });
    expect(wrongType.status).toBe(400);
  });
});

describe('GET /todos', () => {
  test('lists all todos', async () => {
    const a = await seedTodo('first');
    const b = await seedTodo('second');

    const res = await request(app).get('/todos');
    expect(res.status).toBe(200);
    expect(res.body).toHaveLength(2);
    expect(res.body.map((t) => t.id)).toEqual([a.id, b.id]);
  });

  test("filters with ?done=true", async () => {
    await seedTodo('open item');
    await seedTodo('finished item', true);

    const res = await request(app).get('/todos?done=true');
    expect(res.status).toBe(200);
    expect(res.body).toHaveLength(1);
    expect(res.body[0].text).toBe('finished item');
    expect(res.body[0].done).toBe(true);
  });

  test("filters with ?done=false", async () => {
    await seedTodo('open item');
    await seedTodo('finished item', true);

    const res = await request(app).get('/todos?done=false');
    expect(res.status).toBe(200);
    expect(res.body).toHaveLength(1);
    expect(res.body[0].text).toBe('open item');
  });

  test('rejects invalid done value with 400', async () => {
    const res = await request(app).get('/todos?done=maybe');
    expect(res.status).toBe(400);
  });
});

describe('PATCH /todos/:id', () => {
  test('updates text only', async () => {
    const todo = await seedTodo('original');

    const res = await request(app)
      .patch(`/todos/${todo.id}`)
      .send({ text: 'renamed' });

    expect(res.status).toBe(200);
    expect(res.body.text).toBe('renamed');
    expect(res.body.done).toBe(false);
  });

  test('updates done only', async () => {
    const todo = await seedTodo('task');

    const res = await request(app)
      .patch(`/todos/${todo.id}`)
      .send({ done: true });

    expect(res.status).toBe(200);
    expect(res.body.done).toBe(true);
    expect(res.body.text).toBe('task');
  });

  test('accepts partial updates to both fields at once', async () => {
    const todo = await seedTodo('task');

    const res = await request(app)
      .patch(`/todos/${todo.id}`)
      .send({ text: 'updated task', done: true });

    expect(res.status).toBe(200);
    expect(res.body).toMatchObject({ text: 'updated task', done: true });
  });

  test("returns 400 naming unknown field 'priority'", async () => {
    const todo = await seedTodo('task');

    const res = await request(app)
      .patch(`/todos/${todo.id}`)
      .send({ priority: 'high' });

    expect(res.status).toBe(400);
    expect(JSON.stringify(res.body)).toContain('priority');

    // And nothing was changed.
    const list = await request(app).get('/todos');
    expect(list.body[0]).toMatchObject({ id: todo.id, text: 'task' });
  });

  test('returns 404 for nonexistent id', async () => {
    const res = await request(app)
      .patch('/todos/999999')
      .send({ done: true });
    expect(res.status).toBe(404);
  });

  test('rejects invalid field values with 400', async () => {
    const todo = await seedTodo('task');

    const badText = await request(app)
      .patch(`/todos/${todo.id}`)
      .send({ text: 123 });
    expect(badText.status).toBe(400);

    const badDone = await request(app)
      .patch(`/todos/${todo.id}`)
      .send({ done: 'yes' });
    expect(badDone.status).toBe(400);
  });
});

describe('DELETE /todos/:id', () => {
  test('deletes an existing todo with 204', async () => {
    const todo = await seedTodo('doomed');

    const del = await request(app).delete(`/todos/${todo.id}`);
    expect(del.status).toBe(204);

    const list = await request(app).get('/todos');
    expect(list.body).toHaveLength(0);
  });

  test('returns 404 for nonexistent id', async () => {
    const res = await request(app).delete('/todos/999999');
    expect(res.status).toBe(404);
  });
});

